import{_ as t,o as s,c as i,a2 as r}from"./chunks/framework.uw_ZoRon.js";const u=JSON.parse('{"title":"Benchmark dashboard & observer","description":"","frontmatter":{},"headers":[],"relativePath":"about/benchmark-dashboard-and-observer.md","filePath":"about/benchmark-dashboard-and-observer.md"}'),a={name:"about/benchmark-dashboard-and-observer.md"};function o(n,e,h,d,c,l){return s(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="benchmark-dashboard-observer" tabindex="-1">Benchmark dashboard &amp; observer <a class="header-anchor" href="#benchmark-dashboard-observer" aria-label="Permalink to &quot;Benchmark dashboard &amp; observer&quot;">​</a></h1><p>Every performance claim in these docs is something you can watch happen. The dashboard (<code>bench/dashboard</code>, React on Bun, uPlot charts) runs the real runtime, live, and streams its numbers as they&#39;re produced — so you never have to take a figure on trust. It&#39;s also how the project keeps itself honest: each phase &quot;graduates&quot; its scenario from synthetic placeholder data to a real measurement, and the dashboard is where that switch is visible. Open it and you&#39;re watching RUSM&#39;s actual machinery — spawns, messages, supervision, streaming, serving — in motion.</p><p>It has two views fed by one WebSocket stream from a node: a <strong>benchmark view</strong> that drives scenarios and charts their throughput and latency, and a <strong>live observer</strong> that shows the node&#39;s processes the way Erlang&#39;s <code>observer</code> does.</p><h2 id="running-it" tabindex="-1">Running it <a class="header-anchor" href="#running-it" aria-label="Permalink to &quot;Running it&quot;">​</a></h2><p>The dashboard lives in the repo, so clone and run it with <code>make</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes rose-pine-dawn rose-pine-moon catppuccin-latte catppuccin-mocha vitesse-light vitesse-dark one-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D7827E;--shiki-light-font-style:inherit;--shiki-dark:#EA9A97;--shiki-dark-font-style:inherit;--shiki-catpLight:#1E66F5;--shiki-catpLight-font-style:italic;--shiki-catpDark:#89B4FA;--shiki-catpDark-font-style:italic;--shiki-vitLight:#59873A;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#80A665;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#4078F2;--shiki-oneLight-font-style:inherit;--shiki-oneDark:#61AFEF;--shiki-oneDark-font-style:inherit;">git</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> clone</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> https://github.com/archan937/rusm</span><span style="--shiki-light:#797593;--shiki-dark:#908CAA;--shiki-catpLight:#7C7F93;--shiki-catpDark:#9399B2;--shiki-vitLight:#999999;--shiki-vitDark:#666666;--shiki-oneLight:#383A42;--shiki-oneDark:#ABB2BF;"> &amp;&amp;</span><span style="--shiki-light:#B4637A;--shiki-light-font-style:italic;--shiki-dark:#EB6F92;--shiki-dark-font-style:italic;--shiki-catpLight:#D20F39;--shiki-catpLight-font-style:italic;--shiki-catpDark:#F38BA8;--shiki-catpDark-font-style:italic;--shiki-vitLight:#998418;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#B8A965;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#0184BC;--shiki-oneLight-font-style:inherit;--shiki-oneDark:#56B6C2;--shiki-oneDark-font-style:inherit;"> cd</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> rusm</span></span>
<span class="line"><span style="--shiki-light:#D7827E;--shiki-light-font-style:inherit;--shiki-dark:#EA9A97;--shiki-dark-font-style:inherit;--shiki-catpLight:#1E66F5;--shiki-catpLight-font-style:italic;--shiki-catpDark:#89B4FA;--shiki-catpDark-font-style:italic;--shiki-vitLight:#59873A;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#80A665;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#4078F2;--shiki-oneLight-font-style:inherit;--shiki-oneDark:#61AFEF;--shiki-oneDark-font-style:inherit;">make</span><span style="--shiki-light:#EA9D34;--shiki-dark:#F6C177;--shiki-catpLight:#40A02B;--shiki-catpDark:#A6E3A1;--shiki-vitLight:#B56959;--shiki-vitDark:#C98A7D;--shiki-oneLight:#50A14F;--shiki-oneDark:#98C379;"> dashboard</span><span style="--shiki-light:#797593;--shiki-light-font-style:italic;--shiki-dark:#908CAA;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;">      #</span><span style="--shiki-light:#9893A5;--shiki-light-font-style:italic;--shiki-dark:#6E6A86;--shiki-dark-font-style:italic;--shiki-catpLight:#9CA0B0;--shiki-catpLight-font-style:italic;--shiki-catpDark:#6C7086;--shiki-catpDark-font-style:italic;--shiki-vitLight:#A0ADA0;--shiki-vitLight-font-style:inherit;--shiki-vitDark:#758575DD;--shiki-vitDark-font-style:inherit;--shiki-oneLight:#A0A1A7;--shiki-oneLight-font-style:italic;--shiki-oneDark:#7F848E;--shiki-oneDark-font-style:italic;"> builds + starts a node, then the dashboard — open the printed URL</span></span></code></pre></div><p>Pick a scenario (e.g. <strong>spawn storm</strong>, <strong>stream pipe</strong>), hit <strong>Run</strong>, and watch real throughput, latency, and the live observer — everything driven by the real runtime.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>make dashboard</code></td><td>Build + start the benchmark node, then the dashboard (the headline demo).</td></tr><tr><td><code>make node</code></td><td>Start the benchmark node on <code>ws://127.0.0.1:4000</code> (release).</td></tr><tr><td><code>make ui</code></td><td>Start only the dashboard (expects a node already running).</td></tr><tr><td><code>make run SCENARIO=… SECONDS=…</code></td><td>Run a benchmark scenario in the terminal.</td></tr><tr><td><code>make example EX=…</code></td><td>Run a bundled example (<code>host_components</code>, …).</td></tr><tr><td><code>make test</code> / <code>make cov</code></td><td>All Rust + dashboard tests / coverage.</td></tr><tr><td><code>make fmt</code> / <code>make fmt-check</code></td><td>Format / check (Rust + dashboard).</td></tr><tr><td><code>make docs</code> / <code>make docs-build</code></td><td>Live-preview / build this docs site.</td></tr></tbody></table><p>Run <code>make</code> with no target for the full list.</p><h2 id="benchmark-view" tabindex="-1">Benchmark view <a class="header-anchor" href="#benchmark-view" aria-label="Permalink to &quot;Benchmark view&quot;">​</a></h2><p>A menu of scenarios and a <strong>Run</strong> button. Each tick streams: throughput (ops/sec), peak concurrent, latency p50/p95/p99, and a live throughput chart.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Headline</th><th>Real after</th></tr></thead><tbody><tr><td>Spawn storm</td><td>spawns/sec, memory/process</td><td>phase 1</td></tr><tr><td>Message ping-pong</td><td>msgs/sec, round-trip latency</td><td>phase 2</td></tr><tr><td>Fault recovery</td><td>restarts/sec, recovery latency</td><td>phase 3</td></tr><tr><td><strong>Connection storm</strong></td><td>conns/sec, peak, latency</td><td>phase 5 (native), re-measured phase 6</td></tr><tr><td>Connection scale (held-open to the fd ceiling)</td><td>peak concurrent connections</td><td>phase 5</td></tr><tr><td>Fairness under tight loop</td><td>bystanders keep progressing</td><td>phase 6</td></tr><tr><td>Module storm (wasip1, Lunatic head-to-head)</td><td>core-module spawns/sec</td><td>phase 6</td></tr><tr><td>Component storm</td><td>component spawns/sec</td><td>phase 7</td></tr><tr><td>Stream pipe</td><td>bytes/sec between processes</td><td>phase 7</td></tr><tr><td>Distributed fan-out</td><td>cross-node latency</td><td>phase 9</td></tr><tr><td>HTTP throughput + <code>-ts</code> twin</td><td>req/sec (co-resident live demo)</td><td>phase 11</td></tr><tr><td>WS echo + <code>-ts</code> twin</td><td>round-trips/sec (co-resident live demo)</td><td>phase 11</td></tr><tr><td>SSE fan-out + <code>-ts</code> twin</td><td>events/sec (co-resident live demo)</td><td>phase 11</td></tr><tr><td>KV storm</td><td>durable read-modify-writes/sec (ACID commits, redb)</td><td>phase 11</td></tr><tr><td>Pub/sub fan-out</td><td>subscriber deliveries/sec (1 publish → N)</td><td>phase 11</td></tr><tr><td>Crypto ops (TS)</td><td><code>crypto.subtle</code> SHA-256 digests/sec</td><td>phase 11</td></tr><tr><td>Custom bridge</td><td>native custom-bridge calls/sec (guest → host round-trip)</td><td>phase 11</td></tr><tr><td>Dynamic WASM</td><td>dynamic component spawns/sec (compiled once, then cached hot)</td><td>phase 11</td></tr></tbody></table><p>All <strong>twenty-one</strong> scenarios above run <strong>real</strong> engines — none are synthetic (<code>Runner::start_synthetic</code> keeps a runtime-free deterministic preview only for UI development).</p><p>How a number is measured is part of the number, so the dashboard is explicit about it. The <strong>six serving scenarios are co-resident live demos</strong>: each spins up the same real in-process WASM server and drives it through the same load path as the out-of-process <code>rusm-loadtest</code> (balter for HTTP request-rate, a connection-capacity harness for WS/SSE held connections), with the load generator and server sharing the node process. Because they share CPU and hide the network behind loopback, the <strong>fair, credible headline numbers</strong> for serving are still the ones measured <strong>out-of-process</strong> by <code>rusm-loadtest</code> against a live <code>rusm serve</code> port (see <a href="/rusm/deep-dive/serving-http-ws-and-sse">serving HTTP/WS/SSE</a>). The runtime micro-benchmarks (spawns/sec, msgs/sec, restarts/sec, scheduler fairness) stay <strong>in-process</strong> on purpose — they measure the actor core itself where there is no network/server, so in-process is the correct way to measure raw runtime capacity. The three <strong>platform-primitive</strong> scenarios are likewise honest in-process measurements of the capabilities a real app leans on: <strong>KV storm</strong> drives durable read-modify-writes against the embedded <code>rusm-kv</code> (redb) store — the only scenario that touches disk, so its number is the ACID-commit ceiling (writers serialise behind one commit lock; readers are concurrent MVCC); <strong>pub/sub fan-out</strong> is one publisher broadcasting to N subscriber processes (the exact mechanics of <code>rusm-rs</code> <code>pubsub::Topics::publish</code>); and <strong>crypto ops</strong> runs <code>crypto.subtle</code> (native RustCrypto) inside a sandboxed TypeScript guest, so its rate is the honest cost of offering Web Crypto from a JS component.</p><h2 id="live-observer-view" tabindex="-1">Live observer view <a class="header-anchor" href="#live-observer-view" aria-label="Permalink to &quot;Live observer view&quot;">​</a></h2><p>A real-time view of the node (à la Erlang <code>observer</code>): process count, running/waiting, scheduler load bars, total memory, and a per-instance table.</p><h2 id="observability-must-stay-cheap" tabindex="-1">Observability must stay cheap <a class="header-anchor" href="#observability-must-stay-cheap" aria-label="Permalink to &quot;Observability must stay cheap&quot;">​</a></h2><p>Watching a node should never change what you&#39;re watching. Counters are relaxed atomics; the node pushes a <strong>periodic aggregated snapshot</strong> (10–60 Hz), never an event per operation. The per-instance detail table is the only costly part of a snapshot, so it is <strong>toggleable</strong> — off for clean benchmark runs. We prove the overhead is negligible by running a high-rate benchmark <strong>observer-on vs observer-off</strong> (toggle it live with <code>detail off</code> in <code>rusm attach</code>, or the dashboard&#39;s detail switch).</p><h2 id="spawn-storm-how-the-number-is-produced-read-this" tabindex="-1">Spawn-storm: how the number is produced (read this) <a class="header-anchor" href="#spawn-storm-how-the-number-is-produced-read-this" aria-label="Permalink to &quot;Spawn-storm: how the number is produced (read this)&quot;">​</a></h2><p>The spawn-storm is the first scenario on <strong>real</strong> data, so it&#39;s worth being precise about what its <code>ops/sec</code> means and why it&#39;s safe.</p><ul><li><strong>It&#39;s a continuous, multi-core storm.</strong> One background spawner task per (allowed) core hammers <code>rusm-otp</code> — <code>runtime.spawn(...)</code> — as fast as it can. A single sequential loop would be capped by one core; a storm uses many. The tick just <strong>samples</strong> the achieved rate (<code>Δspawned / Δt</code>).</li><li><strong>It measures create <em>and reap</em>.</strong> The spawned processes are trivial and finish immediately, so the rate reflects full lifecycle throughput, not just creation.</li><li><strong>Backpressure is a safety net, not the operating point.</strong> Spawners pause if the <em>live</em> population ever reaches the in-flight cap, so the table can&#39;t grow without bound. But at every profile the population <strong>self-limits far below the cap</strong> (a few hundred live), because spawn rate and reap rate balance out — so &quot;peak concurrent&quot; reflects the real steady-state population, not a configured ceiling.</li><li><strong>Throughput is reap-bound, so the lever is the spawner-to-reaper balance.</strong> The limit is how fast finished processes drain (~one reaper core&#39;s worth each). Too few spawners under-drives the machine; too many starve the reapers and pile processes up <em>without</em> going faster. The sweet spot is spawners ≈ reapers (~half the cores each) — that&#39;s what <strong>Max</strong> uses for peak <em>smooth</em> throughput.</li><li><strong><code>memory</code> shows 0.</strong> Native processes have no per-instance linear memory; that figure becomes real once processes are Wasm instances (Phase 6).</li></ul><h2 id="resource-profiles-the-throughput-dial" tabindex="-1">Resource profiles (the throughput dial) <a class="header-anchor" href="#resource-profiles-the-throughput-dial" aria-label="Permalink to &quot;Resource profiles (the throughput dial)&quot;">​</a></h2><p>A segmented control picks how hard the storm drives the machine. The <strong>spawn worker count is the dial</strong> and is relative to your CPU count; throughput rises with each tier. The in-flight cap is a uniform per-core safety net (memory can&#39;t run away), <strong>not</strong> a per-tier knob — the population self-limits well below it.</p><table tabindex="0"><thead><tr><th>Profile</th><th>Spawn workers</th><th>Throughput (busy 10-core box, release)</th><th>Use it when</th></tr></thead><tbody><tr><td><strong>Light</strong></td><td>~¼ of cores</td><td>~2.1M/s</td><td>speed isn&#39;t the point — leave the machine alone</td></tr><tr><td><strong>Balanced</strong> (default)</td><td>~⅖ of cores</td><td>~2.4M/s</td><td>good throughput with visible room above</td></tr><tr><td><strong>Max</strong></td><td>~½ of cores</td><td>~2.8M/s</td><td>most performant — peak sustained rate, still smooth</td></tr></tbody></table><p><code>Max</code> deliberately stops at ~half the cores: the other half reap, which is the sustained-throughput peak. Pushing spawners higher does <strong>not</strong> go faster — it just starves the reapers and piles processes up. So <code>Max</code> is the fastest profile <em>and</em> keeps the live population to a few hundred (no pile-up). The default is <strong>Balanced</strong> — fast, with headroom, and easy on the laptop. The tier (<code>ResourceProfile</code>) lives in <code>rusm-node</code> <code>profile.rs</code>; the benchmark&#39;s spawn-worker tuning for each tier is in <code>rusm-bench</code> <code>profile_tuning.rs</code>.</p><h2 id="protocol" tabindex="-1">Protocol <a class="header-anchor" href="#protocol" aria-label="Permalink to &quot;Protocol&quot;">​</a></h2><p>The node and clients speak a small JSON protocol (<code>rusm-bench</code> <code>protocol.rs</code>, mirrored in <code>bench/dashboard/src/types.ts</code>):</p><ul><li>Server → client: <code>hello { scenarios, profiles }</code>, <code>tick { frame }</code>, <code>error { message }</code>.</li><li>Client → server: <code>run { scenario }</code>, <code>stop</code>, <code>set_observer_detail { enabled }</code>, <code>set_resource_profile { profile }</code>.</li></ul><p>A <code>Frame</code> carries the scenario, running flag, throughput, latency snapshot, observer snapshot, and the <strong>active resource profile</strong>. The dashboard folds messages into state with a pure reducer (<code>state.ts</code>) — fully unit-tested.</p>`,29)])])}const k=t(a,[["render",o]]);export{u as __pageData,k as default};
